import React, { useState } from "react";
import completeIcon from "./assets/CheckCircle.png";
import updateIcon from "./assets/Group 127.png";
import deleteIcon from "./assets/Group 130.png";

function TaskCard({ task, onComplete, onDelete, onUpdate }) {
  const [isEditing, setIsEditing] = useState(false);
  const [editedTask, setEditedTask] = useState(task);

  const handleUpdate = () => {
    onUpdate(editedTask);
    setIsEditing(false);
  };

  return (
    <div className="task-card">
      {isEditing ? (
        <div className="task-info">
          <input
            value={editedTask.title}
            onChange={(e) => setEditedTask({ ...editedTask, title: e.target.value })}
          />
          <textarea
            value={editedTask.description}
            onChange={(e) => setEditedTask({ ...editedTask, description: e.target.value })}
          />
          <button onClick={handleUpdate}>Save</button>
        </div>
      ) : (
        <div className="task-info">
          <h2>{task.title}</h2>
          <p className="description">{task.description}</p>
          <p className="date">Start date : {task.startDate}</p>
        </div>
      )}

      <div className="icons">
        <div className="task-actions">
          <button className="btn complete" onClick={onComplete}>
            <img src={completeIcon} alt="complete" />
          </button>
          <button className="btn edit" onClick={() => setIsEditing(true)}>
            <img src={updateIcon} alt="edit" />
          </button>
          <button className="btn delete" onClick={onDelete}>
            <img src={deleteIcon} alt="delete" />
          </button>
        </div>
      </div>
    </div>
  );
}

export default TaskCard;
